def load(path):return json.loads((ROOT/path).read_text(encoding='utf-8-sig'))
def sha(path):return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
def evidence(path,needle,role):
    lines=(ROOT/path).read_text(encoding='utf-8-sig').splitlines()
    matches=[i+1 for i,line in enumerate(lines) if needle in line]
    if not matches:raise ValueError((path,needle))
    n=matches[0]
    return {'path':path,'line':n,'passage':lines[n-1].strip(),'role':role,'file_sha256':sha(path)}

